import * as React from 'react';
import {
  Panel,
  PanelType,
  TextField,
  PrimaryButton,
  DefaultButton,
  Stack,
  IStackTokens
} from '@fluentui/react';
import { IInventoryItem } from '../models/IInventoryItem';

export interface IReturnFormProps {
  isOpen: boolean;
  onClose: () => void;
  assetToReturn?: IInventoryItem;
  employeeName: string;
  onSubmitReturn: (reason: string) => void;
}

const stackTokens: IStackTokens = { childrenGap: 15 };

export const ReturnForm: React.FC<IReturnFormProps> = (props) => {
  const [reason, setReason] = React.useState('');

  React.useEffect(() => {
    if (props.isOpen) {
      setReason('');
    }
  }, [props.isOpen]);

  const onSave = () => {
    if (reason.trim()) {
      props.onSubmitReturn(reason);
      props.onClose();
    }
  };

  if (!props.assetToReturn) return null;

  return (
    <Panel
      isOpen={props.isOpen}
      onDismiss={props.onClose}
      type={PanelType.medium}
      headerText="Request Asset Return"
      closeButtonAriaLabel="Close"
    >
      <Stack tokens={stackTokens} style={{ marginTop: '20px' }}>
        <TextField
          label="Asset Name"
          value={props.assetToReturn.assetName || props.assetToReturn.title}
          readOnly
          disabled
        />
        <TextField
          label="Serial Number"
          value={props.assetToReturn.serialNumber}
          readOnly
          disabled
        />
        <TextField
          label="Asset Type"
          value={props.assetToReturn.assetType}
          readOnly
          disabled
        />
        <TextField
          label="Requester"
          value={props.employeeName}
          readOnly
          disabled
        />
        <TextField
          label="Return Reason"
          multiline
          rows={4}
          required
          value={reason}
          onChange={(_, newValue) => setReason(newValue || '')}
          placeholder="Please explain the reason for returning this asset..."
        />
        <Stack horizontal tokens={{ childrenGap: 10 }} style={{ marginTop: '20px' }}>
          <PrimaryButton
            text="Submit Request"
            onClick={onSave}
            disabled={!reason.trim()}
          />
          <DefaultButton
            text="Cancel"
            onClick={props.onClose}
          />
        </Stack>
      </Stack>
    </Panel>
  );
};
